<?php require_once '../config/database.php';require_once '../includes/auth.php';require_once '../includes/ui.php';requireAdmin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id&&in_array($action,['VERIFY','REJECT'])){$status=$action==='VERIFY'?'VERIFIED':'REJECTED';$st=$conn->prepare("UPDATE reports SET status=? WHERE id=? AND status='PENDING'");$st->bind_param('si',$status,$id);$st->execute();$st->close();$msg='Status laporan berhasil diperbarui.';}}$rows=$conn->query("SELECT r.id,r.type,r.item_name,r.description,r.image,r.incident_date,r.status,r.created_at,c.name category_name,l.name location_name,u.name reporter_name,u.email,u.student_status,u.semester,u.fakultas,u.nomor_hp FROM reports r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN locations l ON l.id=r.location_id JOIN users u ON u.id=r.user_id ORDER BY FIELD(r.status,'PENDING','VERIFIED','CLAIMED','RETURNED','REJECTED'),r.created_at DESC");$titleForTop='Verifikasi Laporan';renderHead('Verifikasi Laporan');renderAdminNav('reports');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Verifikasi Laporan</h1><p class="muted">Admin dapat melihat data lengkap pelapor dan penemu sebelum memverifikasi.</p></div></div><?php if($msg): ?><div class="notice notice-ok"><?= e($msg) ?></div><?php endif; ?><div class="grid grid-2 stagger"><?php while($r=$rows->fetch_assoc()): ?><div class="card"><div class="section-head"><span class="pill <?= $r['type']==='FOUND'?'pill-green':'pill-red' ?>"><?= e($r['type']) ?></span><span class="pill pill-yellow"><?= e(statusLabel($r['status'])) ?></span></div><h2><?= e($r['item_name']) ?></h2><div class="meta">Kategori: <?= e($r['category_name']??'-') ?> · Lokasi: <?= e($r['location_name']??'-') ?><br>Tanggal kejadian: <?= e($r['incident_date']) ?></div><hr><h3>Data <?= $r['type']==='FOUND'?'Penemu':'Pelapor' ?></h3><div class="grid grid-2"><div><b>Nama</b><p><?= e($r['reporter_name']) ?></p><b>Status</b><p><?= e($r['student_status']??'-') ?></p><b>Semester</b><p><?= e($r['semester']??'-') ?></p></div><div><b>Fakultas</b><p><?= e($r['fakultas']??'-') ?></p><b>HP</b><p><?= e($r['nomor_hp']??'-') ?></p><b>Email</b><p><?= e($r['email']) ?></p></div></div><h3>Deskripsi</h3><p class="muted" style="white-space:pre-wrap"><?= e($r['description']) ?></p><?php if($r['status']==='PENDING'): ?><div class="actions"><form method="post" class="verify-form"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="VERIFY"><button type="submit" class="btn btn-green">✓ Verifikasi</button></form><form method="post" class="reject-form"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="REJECT"><button type="submit" class="btn btn-red" data-confirm="Yakin menolak laporan ini?">Tolak</button></form></div><?php endif; ?></div><?php endwhile; ?></div></div><?php renderFooter(); ?>
